void trimTrailingSpaces(StringBuilder buffer) {
    int length = buffer.length();
    while (length >= 2 && Character.isWhitespace(buffer.charAt(length - 1)) && Character.isWhitespace(buffer.charAt(length - 2))) {
        length = length - 1;
    }
    if (length != buffer.length()) {
        buffer.setLength(length);
    }
}
